import static org.junit.jupiter.api.Assertions.*;

class LayerPolicy {
    static int rank(String layer) {
        return switch (layer) {
            case "tests" -> 0;
            case "pages" -> 1;
            case "core" -> 2;
            default -> -1;
        };
    }

